class Solution {
public:
    long long maxMatrixSum(vector<vector<int>>& matrix) {
        long long totalSum = 0;
        int negCount = 0;
        int minAbs = INT_MAX;
        for (auto& row : matrix) {
            for (int val : row) {
                if (val < 0) negCount++;
                int absV = abs(val);
                totalSum += absV;
                minAbs = min(minAbs, absV);
            }
        }
        if (negCount % 2 == 1) totalSum -= 2LL * minAbs;
        return totalSum;
    }
};

class Solution {
    public long maxMatrixSum(int[][] matrix) {
        long totalSum = 0;
        int negCount = 0;
        int minAbs = Integer.MAX_VALUE;
        for (int[] row : matrix) {
            for (int val : row) {
                if (val < 0) negCount++;
                int absV = Math.abs(val);
                totalSum += absV;
                minAbs = Math.min(minAbs, absV);
            }
        }
        if (negCount % 2 == 1) totalSum -= 2L * minAbs;
        return totalSum;
    }
}

var maxMatrixSum = function(matrix) {
  let totalSum = 0;
  let negCount = 0;
  let minAbs = Infinity;
  for (const row of matrix) {
    for (const val of row) {
      if (val < 0) negCount++;
      const absV = Math.abs(val);
      totalSum += absV;
      if (absV < minAbs) minAbs = absV;
    }
  }
  if (negCount % 2 === 1) totalSum -= 2 * minAbs;
  return totalSum;
};
